"""Small standalone text filters used by the RTK-compatible command line."""
import difflib
import os
import re
import sys
from collections import Counter


def filter_log(text):
    lines = [x.rstrip("\r") for x in text.splitlines() if x.strip()]
    errors = [x for x in lines if re.search(r"\b(error|fatal|panic|exception)\b", x, re.I)]
    warns = [x for x in lines if re.search(r"\b(warn|warning)\b", x, re.I)]
    infos = [x for x in lines if x not in errors and x not in warns]
    ec, wc, ic = Counter(errors), Counter(warns), Counter(infos)
    out = ["Log Summary", f"   [error] {len(errors)} errors ({len(ec)} unique)",
           f"   [warn] {len(warns)} warnings ({len(wc)} unique)",
           f"   [info] {len(infos)} info messages", ""]
    if errors:
        out.append("[ERRORS]")
        for x, n in ec.items():
            out.append(f"   [×{n}] {x}" if n > 1 else f"   {x}")
        out.append("")
    if warns:
        out.append("[WARNINGS]")
        for x, n in wc.items():
            out.append(f"   [×{n}] {x}" if n > 1 else f"   {x}")
        out.append("")
    return "\n".join(out) + "\n"


def _read(path):
    if path == "-":
        return sys.stdin.read()
    with open(path, encoding="utf-8", errors="replace") as f:
        return f.read()


def filter_unified(text):
    files = {}
    current = None
    for line in text.splitlines():
        if line.startswith("+++ "):
            current = line[4:].split("\t", 1)[0]
            current = current.removeprefix("b/")
            files[current] = []
        elif current is not None and line.startswith(("+", "-")) and not line.startswith(("+++", "---")):
            files[current].append(line)
    out = []
    for name, changes in files.items():
        plus = sum(x.startswith("+") for x in changes)
        minus = sum(x.startswith("-") for x in changes)
        out.append(f"[file] {name} (+{plus} -{minus})")
        out.extend("  " + x for x in changes)
    return "\n".join(out) + ("\n" if out else "")


def file_diff(a, b):
    aa, bb = _read(a).splitlines(), _read(b).splitlines()
    if aa == bb:
        return "[ok] Files are identical\n"
    sm = difflib.SequenceMatcher(a=aa, b=bb, autojunk=False)
    added = removed = modified = 0
    body = []
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == "insert":
            added += j2-j1
            body.extend(f"+   {j+1} {bb[j]}" for j in range(j1,j2))
        elif tag == "delete":
            removed += i2-i1
            body.extend(f"-   {i+1} {aa[i]}" for i in range(i1,i2))
        elif tag == "replace":
            n=min(i2-i1,j2-j1); modified += n
            removed += i2-i1-n; added += j2-j1-n
            for k in range(n):
                body.append(f"-   {i1+k+1} {aa[i1+k]}")
                body.append(f"+   {j1+k+1} {bb[j1+k]}")
            body.extend(f"-   {i+1} {aa[i]}" for i in range(i1+n,i2))
            body.extend(f"+   {j+1} {bb[j]}" for j in range(j1+n,j2))
    return f"{a} → {b}\n   +{added} added, -{removed} removed, ~{modified} modified\n\n" + "\n".join(body) + "\n"


def run_log(args):
    path = args[0] if args and not args[0].startswith("-") else None
    print(filter_log(_read(path) if path else sys.stdin.read()), end="")
    return 0


def run_diff(args):
    if args and args[0] == "-":
        print(filter_unified(sys.stdin.read()), end="")
    elif len(args) >= 2:
        print(file_diff(args[0], args[1]), end="")
        return 0
    else:
        raise SystemExit("usage: diff <FILE1> [FILE2]")

