"""JSON structure and compact-value renderer."""
import json
import sys


def scalar(v, keys=False):
    if keys:
        if v is None: return "null"
        if isinstance(v, bool): return "bool"
        if isinstance(v, int): return "int"
        if isinstance(v, float): return "float"
        if isinstance(v, str): return "string"
    return json.dumps(v, ensure_ascii=False, separators=(",", ":"))


def render(v, indent=0, depth=5, keys=False, level=0, top=False):
    pad = " " * indent
    if isinstance(v, dict):
        if level >= depth and not top:
            return "..."
        if not v: return "{}"
        lines = ["{"]
        for k in sorted(v):
            val = v[k]
            key = json.dumps(k, ensure_ascii=False)
            if isinstance(val, (dict, list)):
                rendered = render(val, indent+2, depth, keys, level+1)
                lines.append(" "*(indent+2) + key[1:-1] + ":")
                lines.extend(" "*(indent+2) + ln for ln in rendered.splitlines())
            else:
                lines.append(" "*(indent+2) + key[1:-1] + ": " + scalar(val, keys))
        lines.append(pad + "}")
        return "\n".join(lines)
    if isinstance(v, list):
        if not v: return "[]"
        if all(not isinstance(x, (dict,list)) for x in v):
            if keys:
                types = sorted(set(scalar(x, True) for x in v))
                return "[" + ", ".join(types) + f"] ({len(v)})"
            return json.dumps(v, ensure_ascii=False, separators=(", ", ": "))
        if level >= depth:
            return "..."
        lines = ["["]
        for item in v:
            itemstr = render(item, indent+2, depth, keys, level+1)
            parts = itemstr.splitlines()
            lines.extend(" "*(indent+2)+p for p in parts)
            lines[-1] += ","
        lines.append(pad + "]")
        if keys and v and isinstance(v[0], dict):
            lines[-1] += f" ({len(v)})"
        return "\n".join(lines)
    return scalar(v, keys)


def run_json(args):
    path = None
    keys = False
    depth = 5
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--keys-only": keys = True
        elif a in ("-d", "--depth") and i+1 < len(args):
            i += 1
            try: depth = max(0, int(args[i]))
            except ValueError: pass
        elif a.startswith("--depth="):
            try: depth = max(0, int(a.split("=",1)[1]))
            except ValueError: pass
        elif not a.startswith("-"): path = a
        i += 1
    if path is None:
        print("rtk: error: the following required arguments were not provided:\n  <FILE>", file=sys.stderr)
        return 2
    try:
        with open(path, encoding="utf-8") as f: value = json.load(f)
    except OSError as exc:
        label = "No such file or directory" if isinstance(exc, FileNotFoundError) else "Permission denied"
        print(f"rtk: Failed to read file: {path}: {label} (os error {exc.errno})", file=sys.stderr)
        return 1
    except json.JSONDecodeError as exc:
        print(f"rtk: Failed to parse JSON: {exc}", file=sys.stderr)
        return 1
    print(render(value, depth=depth, keys=keys, top=True))
    return 0

