"""Compact git command adapter."""
import subprocess
import sys

def _run(args):
    return subprocess.run(["git", *args], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)

def run_git(args):
    args=list(args)
    if not args:
        return 0
    sub=args[0]
    if sub == "status":
        short="--short" in args or "-s" in args
        p=_run(["status", "--porcelain=v1", "-uall"])
        if p.returncode:
            sys.stderr.write(p.stderr); return p.returncode
        if not short:
            b=_run(["rev-parse","--abbrev-ref","HEAD"])
            branch=b.stdout.strip() if not b.returncode else "HEAD"
            print("* "+branch)
        sys.stdout.write(p.stdout)
        return 0
    if sub == "log":
        n="5"
        for i,a in enumerate(args):
            if a in ("-n","--max-count") and i+1<len(args): n=args[i+1]
            elif a.startswith("-") and a[1:].isdigit(): n=a[1:]
        fmt="%h %s"
        if "--oneline" not in args:
            fmt += " (%cr) <%an>"
        passthrough=[a for a in args[1:] if a not in ("--oneline",) and not a.startswith("-")]
        p=_run(["log", "-n",n,"--format="+fmt,*passthrough])
        sys.stdout.write(p.stdout); sys.stderr.write(p.stderr); return p.returncode
    if sub == "diff":
        p=_run(["diff","--no-color",*args[1:]])
        if p.returncode: sys.stderr.write(p.stderr); return p.returncode
        lines=p.stdout.splitlines()
        files=[]; current=None; hunks=[]
        for line in lines:
            if line.startswith("diff --git "):
                if current is not None: files.append((current,hunks))
                bits=line.split(" b/",1); current=bits[1] if len(bits)>1 else line
                hunks=[]
            elif line.startswith("@@") or (current is not None and line.startswith(("+","-")) and not line.startswith(("+++","---"))):
                hunks.append(line)
        if current is not None: files.append((current,hunks))
        if not files: return 0
        for name,h in files:
            adds=sum(x.startswith("+") and not x.startswith("+++") for x in h)
            dels=sum(x.startswith("-") and not x.startswith("---") for x in h)
            print(f"{name} | {adds+dels} {'+' if adds else ''}{adds} {'-' if dels else ''}{dels}")
        print("\n--- Changes ---")
        for name,h in files:
            print("\n"+name)
            for x in h: print("  "+x)
            adds=sum(x.startswith("+") and not x.startswith("+++") for x in h)
            dels=sum(x.startswith("-") and not x.startswith("---") for x in h)
            print(f"  +{adds} -{dels}")
        return 0
    p=_run(args)
    if p.returncode:
        sys.stdout.write(p.stdout); sys.stderr.write(p.stderr); return p.returncode
    # Suppress routine git command chatter; summarize successful mutations.
    if sub in ("add","restore","checkout","switch","fetch","pull","push","reset","stash","commit"):
        if sub=="add":
            stat=_run(["diff","--cached","--shortstat"])
            s=stat.stdout.strip()
            if s:
                import re
                files=re.search(r"(\d+) files? changed",s)
                print(f"ok {s}" if files else "ok")
            else: print("ok")
        elif sub=="commit":
            h=_run(["rev-parse","--short","HEAD"])
            print("ok "+h.stdout.strip())
        else: print("ok")
        return 0
    sys.stdout.write(p.stdout); sys.stderr.write(p.stderr); return 0

