def run_ls(args):
    if any(x in ('-h','--help') for x in args):
        print('List directory contents with token-optimized output (proxy to native ls)\n\nUsage: executable ls [OPTIONS] [ARGS]...\n\nArguments:\n  [ARGS]...  Arguments passed to ls (supports all native ls flags like -l, -a, -h, -R)\n\nOptions:\n  -v, --verbose...     Verbosity level (-v, -vv, -vvv)\n      --ultra-compact  Ultra-compact mode: ASCII icons, inline format (Level 2 optimizations)\n      --skip-env       Set SKIP_ENV_VALIDATION=1 for child processes (Next.js, tsc, lint, prisma)\n  -h, --help           Print help')
        return 0
    paths=[x for x in args if not x.startswith('-')] or ['.']
    show_all=any('a' in x[1:] for x in args if x.startswith('-'))
    long_mode=any('l' in x[1:] for x in args if x.startswith('-'))
    recursive=any('R' in x[1:] for x in args if x.startswith('-'))
    def size_text(n):
        if n >= 1024*1024: return f'{n/(1024*1024):.1f}M'
        if n >= 1024: return f'{n/1024:.1f}K'
        return f'{n}B'
    for path in paths:
        if os.path.isfile(path):
            try: print(f'{path}  {size_text(os.path.getsize(path))}')
            except OSError: print(path)
            continue
        try: entries=list(os.scandir(path)) if os.path.isdir(path) else []
        except OSError as e:
            print(f'ls: {path}: {e.strerror}',file=sys.stderr); continue
        if os.path.isdir(path):
            names=[x for x in entries if show_all or not x.name.startswith('.')]
            if recursive:
                for root, dirs, files in os.walk(path, followlinks=False):
                    dirs[:]=[d for d in dirs if show_all or not d.startswith('.')]
                    if root==path: continue
                    try: names.extend(os.scandir(root))
                    except OSError: pass
        else:
            print(f'ls: {path}: No such file or directory',file=sys.stderr); continue
        dirs=[]; files=[]
        for e in names:
            try:
                isdir=e.is_dir(follow_symlinks=False)
                size=os.path.getsize(e.path)
                if isdir: dirs.append(e.name+'/')
                else: files.append(f'{e.name}  {size_text(size)}')
            except OSError:
