        ext=Counter(os.path.splitext(p)[1] or '.none' for p in files)
        summary=sorted(ext.items(),key=lambda kv:(-kv[1],kv[0]=='.none',kv[0]))
        print('\next: '+' '.join(f'{key}({value})' for key,value in summary))
    return cp.returncode

